def nm_for(s, extra=True):
    basis=[np.ones_like(t), s, t, s*t] if extra else [np.ones_like(t), s]
    cols=[B*P**j for B in basis for j in range(4)]
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
    return np.mean((dP_dt-X@c)**2)/np.var(dP_dt)
fams={
 'exp':lambda k,b: 1-np.exp(-k*t**b),
 'tanh':lambda k,b: np.tanh(k*t**b),
 'tanhlin':lambda k,b: np.tanh(k*t)*0+np.tanh(k*t**b),
 'rat':lambda k,b: t**b/(k+t**b),
 'texp':lambda k,b: t**b*np.exp(-k*t),
 'log':lambda k,b: np.log1p(k*t**b),
 'sig':lambda k,b: 1/(1+np.exp(-k*(t-b))),
}
